'use client';

import { useEffect, useState } from 'react';
import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { formatCurrency, formatDateTime } from '@/lib/utils';
import { 
  UserIcon, 
  PlusIcon, 
  MagnifyingGlassIcon,
  EnvelopeIcon,
  PhoneIcon,
  MapPinIcon,
  PencilIcon,
  TrashIcon
} from '@heroicons/react/24/outline';

// Mock customers data
const mockCustomers = [
  {
    id: '1',
    name: 'John Smith',
    email: 'john.smith@email.com',
    phone: '+1 (555) 123-4567',
    address: '123 Main St, City, State 12345',
    totalPurchases: 45,
    totalSpent: 2345.67,
    lastPurchase: '2024-03-12T10:30:00Z',
    status: 'active',
    memberSince: '2023-01-15'
  },
  {
    id: '2',
    name: 'Sarah Johnson',
    email: 'sarah.j@email.com',
    phone: '+1 (555) 987-6543',
    address: '456 Oak Ave, Town, State 67890',
    totalPurchases: 28,
    totalSpent: 1567.89,
    lastPurchase: '2024-03-10T14:20:00Z',
    status: 'active',
    memberSince: '2023-03-22'
  },
  {
    id: '3',
    name: 'Mike Wilson',
    email: 'mike.w@email.com',
    phone: '+1 (555) 246-8135',
    address: '789 Pine Rd, Village, State 11223',
    totalPurchases: 67,
    totalSpent: 3456.78,
    lastPurchase: '2024-03-08T09:15:00Z',
    status: 'inactive',
    memberSince: '2022-11-08'
  },
];

const customerStatuses = ['All', 'Active', 'Inactive'];

export default function CustomersPage() {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');

  const filteredCustomers = mockCustomers.filter(customer => {
    const matchesSearch = customer.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         customer.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         customer.phone.includes(searchTerm);
    const matchesStatus = statusFilter === 'All' || customer.status === statusFilter.toLowerCase();
    return matchesSearch && matchesStatus;
  });

  const getStatusColor = (status: string) => {
    return status === 'active' ? 'status-success' : 'status-error';
  };

  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Customers Header */}
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-2xl font-bold text-primary">Customer Management</h1>
              <p className="text-sm text-text-secondary">Manage customer information and purchase history</p>
            </div>
            <button className="btn-primary flex items-center space-x-2">
              <PlusIcon className="h-4 w-4" />
              <span>Add Customer</span>
            </button>
          </div>

          {/* Customer Stats */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-primary/10 rounded-lg">
                  <UserIcon className="h-6 w-6 text-primary" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-text-secondary">Total Customers</p>
                  <p className="text-2xl font-bold text-primary">{mockCustomers.length}</p>
                </div>
              </div>
            </div>
            
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-success/10 rounded-lg">
                  <UserIcon className="h-6 w-6 text-success" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-text-secondary">Active Customers</p>
                  <p className="text-2xl font-bold text-success">
                    {mockCustomers.filter(c => c.status === 'active').length}
                  </p>
                </div>
              </div>
            </div>
            
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-info/10 rounded-lg">
                  <UserIcon className="h-6 w-6 text-info" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-text-secondary">New This Month</p>
                  <p className="text-2xl font-bold text-info">12</p>
                </div>
              </div>
            </div>
            
            <div className="card p-6">
              <div className="flex items-center">
                <div className="p-3 bg-warning/10 rounded-lg">
                  <UserIcon className="h-6 w-6 text-warning" />
                </div>
                <div className="ml-4">
                  <p className="text-sm font-medium text-text-secondary">Inactive</p>
                  <p className="text-2xl font-bold text-warning">
                    {mockCustomers.filter(c => c.status === 'inactive').length}
                  </p>
                </div>
              </div>
            </div>
          </div>

          {/* Search and Filters */}
          <div className="card p-4">
            <div className="flex flex-col lg:flex-row gap-4">
              <div className="flex-1">
                <div className="relative">
                  <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-text-secondary" />
                  <input
                    type="text"
                    placeholder="Search customers..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="input-field pl-10 w-full"
                  />
                </div>
              </div>
              <div className="flex gap-2">
                <select
                  value={statusFilter}
                  onChange={(e) => setStatusFilter(e.target.value)}
                  className="input-field"
                >
                  {customerStatuses.map(status => (
                    <option key={status} value={status}>{status}</option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          {/* Customers Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredCustomers.map(customer => (
              <div key={customer.id} className="card p-6 hover-lift">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center space-x-3">
                    <div className="h-10 w-10 bg-surface rounded-full flex items-center justify-center">
                      <UserIcon className="h-5 w-5 text-primary" />
                    </div>
                    <div>
                      <h3 className="font-medium text-primary">{customer.name}</h3>
                      <span className={`px-2 py-1 text-xs rounded-full ${getStatusColor(customer.status)}`}>
                        {customer.status}
                      </span>
                    </div>
                  </div>
                  <div className="flex space-x-1">
                    <button className="text-info hover:text-info/80">
                      <PencilIcon className="h-4 w-4" />
                    </button>
                    <button className="text-error hover:text-error/80">
                      <TrashIcon className="h-4 w-4" />
                    </button>
                  </div>
                </div>
                
                <div className="space-y-2 text-sm">
                  <div className="flex items-center space-x-2 text-text-secondary">
                    <EnvelopeIcon className="h-4 w-4" />
                    <span>{customer.email}</span>
                  </div>
                  <div className="flex items-center space-x-2 text-text-secondary">
                    <PhoneIcon className="h-4 w-4" />
                    <span>{customer.phone}</span>
                  </div>
                  <div className="flex items-center space-x-2 text-text-secondary">
                    <MapPinIcon className="h-4 w-4" />
                    <span className="truncate">{customer.address}</span>
                  </div>
                </div>
                
                <div className="border-t border-divider pt-4 mt-4">
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <p className="text-text-secondary">Total Purchases</p>
                      <p className="font-medium text-primary">{customer.totalPurchases}</p>
                    </div>
                    <div>
                      <p className="text-text-secondary">Total Spent</p>
                      <p className="font-medium text-primary">{formatCurrency(customer.totalSpent)}</p>
                    </div>
                    <div>
                      <p className="text-text-secondary">Last Purchase</p>
                      <p className="font-medium text-primary">
                        {formatDateTime(customer.lastPurchase)}
                      </p>
                    </div>
                    <div>
                      <p className="text-text-secondary">Member Since</p>
                      <p className="font-medium text-primary">{customer.memberSince}</p>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </Layout>
    </AuthGuard>
  );
}
